local SugarRefiner = {}
local PRODUCTS = {
    raw_sugar = { name = "Surov sladkor", caneCost = 3, waterCost = 1, fuelCost = 1, time = 3, cost = 30, sweetness = 50, happiness = 1, description = "Surov sladkor iz sladkornega trsa." },
    refined_sugar = { name = "Rafiniran sladkor", caneCost = 4, waterCost = 2, fuelCost = 1, time = 5, cost = 80, sweetness = 70, happiness = 2, prestige = 2, description = "Rafiniran sladkor z visoko čistostjo." },
    white_sugar = { name = "Beli sladkor", caneCost = 5, waterCost = 2, fuelCost = 2, time = 7, cost = 180, sweetness = 85, happiness = 3, prestige = 4, description = "Beli sladkor za fine sladice." },
    sugar_loaf = { name = "Sladkorni hlebec", caneCost = 6, waterCost = 3, fuelCost = 2, time = 9, cost = 380, sweetness = 90, happiness = 4, prestige = 7, description = "Sladkorni hlebec v stožčasti obliki." },
    silver_treated_sugar = { name = "Srebrno obdelan sladkor", caneCost = 7, waterCost = 3, silverCost = 1, fuelCost = 2, time = 12, cost = 800, sweetness = 95, happiness = 6, prestige = 13, description = "Srebrno obdelan sladkor za kraljeve sladice." },
    royal_pure_sugar = { name = "Kraljevski čisti sladkor", caneCost = 10, waterCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, fuelCost = 3, time = 17, cost = 1800, sweetness = 100, happiness = 12, prestige = 35, description = "Veliki kraljevski čisti sladkor z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Sladkornjaška delavnica", cost = { gold = 320, wood = 140, stone = 200 }, upkeep = 8, qualityBonus = 5 },
    boiling_house = { name = "Vrelnica", cost = { gold = 1100, wood = 280, stone = 400, fuel = 8 }, upkeep = 27, qualityBonus = 18 },
    crystallization_room = { name = "Kristalizirnica", cost = { gold = 2500, wood = 350, stone = 700, silver = 40, water = 10 }, upkeep = 60, qualityBonus = 30 },
    royal_sugar_atelier = { name = "Kraljevski atelje sladkorja", cost = { gold = 10000, wood = 600, stone = 1100, gold = 80, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 45 },
}
SugarRefiner.caneStock = 22; SugarRefiner.waterStock = 18; SugarRefiner.fuelStock = 14; SugarRefiner.silverStock = 8; SugarRefiner.goldStock = 6; SugarRefiner.jewelStock = 6
SugarRefiner.productStock = {}; SugarRefiner.buildings = {}; SugarRefiner.maker = nil; SugarRefiner.activeMaking = {}; SugarRefiner.totalProducts = 0; SugarRefiner.dayTimer = 0
function SugarRefiner.init() SugarRefiner.caneStock=22; SugarRefiner.waterStock=18; SugarRefiner.fuelStock=14; SugarRefiner.silverStock=8; SugarRefiner.goldStock=6; SugarRefiner.jewelStock=6; SugarRefiner.productStock={}; SugarRefiner.buildings={}; SugarRefiner.maker=nil; SugarRefiner.activeMaking={}; SugarRefiner.totalProducts=0; SugarRefiner.dayTimer=0; print("[SugarRefiner] Royal Sugar Refiner System initialized (6 products, 4 buildings)") end
function SugarRefiner.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SugarRefiner.maker={name=n or ("Sladkornjaš "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sladkornjaš najet: %s (spretnost: %d)",SugarRefiner.maker.name,s),"success") end; return true end
function SugarRefiner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SugarRefiner.build(id) local ok,e=SugarRefiner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SugarRefiner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SugarRefiner.getQualityBonus() local b=0; for _,bd in ipairs(SugarRefiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SugarRefiner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.caneCost and SugarRefiner.caneStock<(d.caneCost or 0) then return false,"Premalo trsa" end; if d.waterCost and SugarRefiner.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.fuelCost and SugarRefiner.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.silverCost and SugarRefiner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SugarRefiner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SugarRefiner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SugarRefiner.buildings==0 then return false,"Potrebna delavnica" end; if not SugarRefiner.maker then return false,"Potreben sladkornjaš" end; return true end
function SugarRefiner.make(pt,qty) qty=qty or 5; local ok,e=SugarRefiner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.caneCost then SugarRefiner.caneStock=SugarRefiner.caneStock-d.caneCost*qty end; if d.waterCost then SugarRefiner.waterStock=SugarRefiner.waterStock-d.waterCost*qty end; if d.fuelCost then SugarRefiner.fuelStock=SugarRefiner.fuelStock-d.fuelCost*qty end; if d.silverCost then SugarRefiner.silverStock=SugarRefiner.silverStock-d.silverCost*qty end; if d.goldCost then SugarRefiner.goldStock=SugarRefiner.goldStock-d.goldCost*qty end; if d.jewelCost then SugarRefiner.jewelStock=SugarRefiner.jewelStock-d.jewelCost*qty end; local t=d.time; if SugarRefiner.maker then t=math.max(1,t-math.floor(SugarRefiner.maker.skill/12)) end; table.insert(SugarRefiner.activeMaking,{id="sugar_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sweetness=d.sweetness or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SugarRefiner.completeMaking(m) local q=1.0+(SugarRefiner.getQualityBonus()/100); if SugarRefiner.maker then q=q+(SugarRefiner.maker.skill/180) end; q=math.min(2.0,q); SugarRefiner.productStock[m.productType]=(SugarRefiner.productStock[m.productType] or 0)+m.quantity; SugarRefiner.totalProducts=SugarRefiner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SugarRefiner.maker then SugarRefiner.maker.itemsMade=SugarRefiner.maker.itemsMade+m.quantity; if math.random()<0.20 then SugarRefiner.maker.skill=math.min(100,SugarRefiner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sladkor izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sugar.completed",{productName=m.productName,sweetness=m.sweetness,happiness=m.happiness}) end end
function SugarRefiner.update(dt) if not _G.state then return end; SugarRefiner.dayTimer=SugarRefiner.dayTimer+dt; if SugarRefiner.dayTimer>=30 then SugarRefiner.dayTimer=0; for i=#SugarRefiner.activeMaking,1,-1 do local m=SugarRefiner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SugarRefiner.completeMaking(m); table.remove(SugarRefiner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SugarRefiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SugarRefiner.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SugarRefiner.getStats() return {caneStock=SugarRefiner.caneStock,waterStock=SugarRefiner.waterStock,fuelStock=SugarRefiner.fuelStock,silverStock=SugarRefiner.silverStock,goldStock=SugarRefiner.goldStock,jewelStock=SugarRefiner.jewelStock,productStock=SugarRefiner.productStock,numBuildings=#SugarRefiner.buildings,hasMaker=SugarRefiner.maker~=nil,makerName=SugarRefiner.maker and SugarRefiner.maker.name or "—",makerSkill=SugarRefiner.maker and SugarRefiner.maker.skill or 0,activeMaking=#SugarRefiner.activeMaking,totalProducts=SugarRefiner.totalProducts} end
return SugarRefiner
